SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f2c47323ed0300cae625304e870298722acfa1ce/content/books/zizhi-tongjian/vol-286/year-0947/part-12/sources/library/jiuwudaishi-099-april-appointments/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002429；EPUB电子本，纸本及异文待核", "id": "e67c334a-9e54-5f26-8a7b-aad44d76df40"}, {"title": "旧五代史·卷一百〇五", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f2c47323ed0300cae625304e870298722acfa1ce/content/books/zizhi-tongjian/vol-286/year-0947/part-12/sources/library/jiuwudaishi-105-liu-xin/source.txt", "note": "《旧五代史》卷一百〇五，段落 jiu-wudaishi-205deb4a7860-p002518；EPUB电子本，纸本及异文待核", "id": "254aba34-46bc-5ef0-bf17-f80cb24f7135"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f2c47323ed0300cae625304e870298722acfa1ce/content/books/zizhi-tongjian/vol-286/year-0947/part-12/sources/library/tongjian-286-947-return-april/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003401；电子底本待考，分段待核", "id": "a6f8049e-ea12-5160-a527-1d0e42e1c89d"}, {"title": "新五代史·卷三十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f2c47323ed0300cae625304e870298722acfa1ce/content/books/zizhi-tongjian/vol-286/year-0947/part-12/sources/library/xinwudaishi-030-wang-zhang/source.txt", "note": "《新五代史》卷三十，段落 xin-wudaishi-b08f244b9241-p001107；EPUB电子本，纸本及异文待核", "id": "570d34ad-24d6-5314-8971-5de1dae09ad1"}, {"title": "新五代史·卷七十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/f2c47323ed0300cae625304e870298722acfa1ce/content/books/zizhi-tongjian/vol-286/year-0947/part-12/sources/library/xinwudaishi-070-liu-min/source.txt", "note": "《新五代史》卷七十，段落 xin-wudaishi-b08f244b9241-p003444；EPUB电子本，纸本及异文待核", "id": "1448e9b3-dd5f-5ed0-b3f4-7e03af09f032"}, {"title": "资治通鉴·后汉纪一", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/tongjian-286-947-xuzhou-march/source.txt", "note": "《资治通鉴》后汉纪一，段落 zizhi-tongjian-a63549944a71-p003400；电子底本待考，分段待核", "id": "a967c8c3-a86b-5a6a-935c-f02f4127bba5"}, {"title": "旧五代史·卷九十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a5f6c36376aec96cc635a266cd774a64d3733ea7/content/books/zizhi-tongjian/vol-286/year-0947/part-10/sources/library/jiuwudaishi-099-march-rising/source.txt", "note": "《旧五代史》卷九十九，段落 jiu-wudaishi-205deb4a7860-p002428；EPUB电子本，纸本及异文待核", "id": "1b396d07-3d8c-5388-8d7c-afd93f0c779b"}, {"title": "新五代史·卷67·吴越世家·钱弘佐救福州", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/bf9e990066dba1dacd217dcd86a7c0d28b93b91c/content/books/zizhi-tongjian/vol-285/year-0946/part-04/sources/library/xinwudaishi-067-fuzhou-relief/source.txt", "note": "《新五代史》卷67·吴越世家·钱弘佐救福州，段落 xin-wudaishi-b08f244b9241-p003373；已回查卷题、上下文与传主，纸本及异文待核。", "id": "d49e8d36-e61b-5b0f-a6aa-358fa4c4e901"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "高勋", "aliases": ["高勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋阁门使。946年十二月丙寅，杜重威派他向契丹送降表，耶律德光赐诏接受。与军将关勋分别识别；生卒年本批未核。", "biography": null, "status": "draft", "id": "ea4f636d-1bb8-5b40-a94d-0da7caf7ebea"}, {"name": "孙汉韶", "aliases": ["孫漢韶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：孙汉韶，武定节度使、合兵奏者。", "biography": null, "status": "draft", "id": "5e4dd4c6-73f4-51a3-a55b-930f6b95eac2"}, {"name": "张筠（吴越统军使）", "aliases": ["張筠（吳越統軍使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越统军使。《新五代史》记钱弘佐派他与赵承泰等救援福州；《资治通鉴》947年条记他返回钱唐。与早期后梁将领张筠分别建档，生卒年未载。", "biography": null, "status": "draft", "id": "27c4d4a1-4846-5d28-b74e-551d8586bbe6"}, {"name": "余安", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越将领。947年率水军从海道救援福州，三月己亥到白虾浦，与城内军队夹击南唐军，后领兵入福州，接管李仁达所部。生卒年未载。", "biography": null, "status": "draft", "id": "a2c3f143-466f-563b-a921-40cb3fdfd3a1"}, {"name": "钱弘佐", "aliases": ["錢弘佐"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲许氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "0d604e68-f71f-5263-9e8f-80de6e9feb32"}, {"name": "鲍修让", "aliases": ["鮑修讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴越东南安抚使。947年钱弘佐派他率军驻守福州。生卒年未载。", "biography": null, "status": "draft", "id": "10a9b07f-dbdb-57a9-b923-561e2cfa6d86"}, {"name": "钱弘倧", "aliases": ["錢弘倧"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲鹿氏。939年条下的王室家属追述提及他，出生年份本句未载。", "biography": null, "status": "draft", "id": "141c421e-2a7d-5b59-91f9-bf5ec3f726df"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "刘崇（刘知远弟）", "aliases": ["劉崇（劉知遠弟）", "刘旻", "劉旻"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的弟弟，后来名刘旻。947年任太原尹、知府事。与朱温早年寄居的萧县刘崇分别建档，具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "edf0bd63-ab6d-577e-8623-9f2d759b6d97"}, {"name": "梁晖", "aliases": ["梁暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "滏阳武装首领，率数百人向刘知远请求效力，受李谷指示袭击相州。947年二月丁丑夜攻入相州，守将突围离开，梁晖自称留后并上报。生卒年暂未录入。", "biography": null, "status": "draft", "id": "5d3513b4-fa20-5947-9ffb-c3d71ae4cbfc"}, {"name": "高唐英", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹所任地方长官。947年二月刘知远即位后，被任命为彰德节度使；梁晖袭取相州时，他尚未到任。《旧五代史》同记相州節度使，《辽史》官号另作昭德，分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "4b35bffc-c928-554e-8e55-22b4618620ab"}, {"name": "王继弘", "aliases": ["王繼弘", "王继宏", "王繼宏"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后汉相州节度使。《资治通鉴》记他后来收葬相州城中遗骨；《旧五代史》作王继宏，将发现遗骨记在乾祐年间。生卒年未载。", "biography": null, "status": "draft", "id": "c58b8745-38bc-50f1-9770-848f81d79849"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "刘信（刘知远从弟）", "aliases": ["劉信（劉知遠從弟）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘知远的从弟，后汉将领。947年领义成节度使，兼侍卫马军都指挥使。与先前吴国将领刘信分别建档，生卒年尚未录入。", "biography": null, "status": "draft", "id": "a2f0a9f1-8401-5b6c-9a1e-3a49051af567"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "王章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "魏州南乐人，曾任孔目官，随刘知远到太原。947年任权三司使。具体生卒年尚未录入。", "biography": null, "status": "draft", "id": "154bd412-f052-5459-9c17-951cfcd91759"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "留从效率领军队返回泉州", "start_year": 947, "end_year": 947, "time_original": "947年三月条下，具体日未载", "dynasty": "五代十国", "description": "留从效率领军队返回泉州。", "phases": [], "location_name": "泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "39a5c5e5-633f-54af-ae79-2d1da7123304"}, {"title": "留从效称泉州贫瘠、赋税沉重，劝南唐驻军离开", "start_year": 947, "end_year": 947, "time_original": "947年三月条下，具体日未载", "dynasty": "五代十国", "description": "留从效称泉州贫瘠、赋税沉重，劝南唐驻军离开。", "phases": [], "location_name": "泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9fb0a4b3-4d40-5f85-937e-b7f75d607bd7"}, {"title": "留从效设宴饯行，南唐驻将不得已率军离开泉州", "start_year": 947, "end_year": 947, "time_original": "947年三月条下，具体日未载", "dynasty": "五代十国", "description": "留从效设宴饯行，南唐驻将不得已率军离开泉州。", "phases": [], "location_name": "泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c1ed4546-171f-5cd9-bae0-cdb50159b0d2"}, {"title": "李璟未能约束留从效，加授他检校太傅", "start_year": 947, "end_year": 947, "time_original": "947年三月条下，具体日未载", "dynasty": "五代十国", "description": "李璟未能约束留从效，加授他检校太傅。", "phases": [], "location_name": "南唐朝廷至泉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bbd8c758-00f1-550a-ad69-384ccb8b2f90"}, {"title": "耶律德光离开大梁，带走晋朝官员、军人、宫人及府库财物", "start_year": 947, "end_year": 947, "time_original": "947年三月壬寅", "d